const broker = flow.get('broker');
const spaceId = "GrthuZrX4aRYxNypq";
const userId = "62f4805b23c63d2784fed286";
// 功能
// **erp数据详情表中新增加的的数据需要区分立库和普通库**
// 1. 新增加的数据为普通库、区分是否是项目属性的物料
//    1. 错误提示1：如果基础物料没有该物料、就提示未查找到该物料
// 2. 新增加的数据为立体库
//    1. 物料信息维护表中带有装箱量
//    2. 需要根据到货数量去查找表有是否有该原料
//    3. 如果有、是否带项目属性
//    4. 来区分该分配几个空箱并写到WMS分配表中
//    5. 提示错误1：数据详情表中是否有该原料、如果没有在erp数据详情中提示、未找到该物料
//    6. 提示错误2：库中是否有空箱、如果没有、那么提示库中没有多余的空箱了


// let q = [['name', '=', '' ], ['doc_type__c', '=', "采购订单"]];
// const Arr = await broker.call('@pc_erp_data__c.find', { filters: [...q] } ); 


// erp数据详情表 查找条件为 name 为 初始 | 采购订单
const Arr = (await broker.call('@pc_erp_data__c.find', { 
    filters: [['doc_type__c', '=', "采购订单"]]
 })).filter(v => v.name == "" || v.name == undefined)
if(!Arr.length) return;

// node.warn(Arr);
// return



const documentNumber = Arr[0].document_number__c; // erp单号
const docType = Arr[0].doc_type__c; // 单据类型：采购订单...
const id = Arr[0]._id; // 635bddb2ba8ddd4d1068aadb
const materialCode = Arr[0].material_code__c.trim(); // 物料代码：B.004.004.026 
const materialName = Arr[0].material_name__c.trim(); // 物料名称：8PT3599 
const specification = Arr[0].specifications__c.trim(); // 规格型号：转接件（上） 
const arrivalQuantity = Arr[0].arrive_number__c; // 到货数量: 80 
const projectAttr = Arr[0].project_attr__c.trim(); // 项目属性: P20015
// 维护表中的数据千万不能有空格啊 真坑

let query = [
    ['material_code__c', '=', materialCode], 
    ['material_name__c', '=', materialName], 
    ['specifications__c', '=', specification]
];
const fDocs = await broker.call('@pc_material_data__c.find', { filters: [...query] } ); // 物料基础信息表
// node.warn(fDocs[0]);
// return



if(fDocs.length === 1){
    // 如果是立体库
    if (fDocs[0].warehouse_name__c === '立体库'){
        // 如果是立库就有装箱量
        // TODO: 1 更新erp-数据详情表
        // TODO: 2 查询WMS容器操作记录表 是否有该原料及项目情况
        // TODO: 3 写入xxx表中分配几个空箱
        // TODO: 4 库中是否有空箱、如果没有、那么提示库中没有多余的空箱了 

        // node.warn(111);
        // 装箱量 - 立库才有装箱量 - 根据物料基础数据维护表中
        const QTY = fDocs[0].binning_number__c;

        //排、列、层、箱号、项目属性、放入数量
        async function addDataProject(row,col,lay,boxNumber, projectAttribute, Quantity) { 
            // node.warn("执行次数"); 
            let newDoc3 = {
                // 执行时间：time__c
                container_type__c: '料箱', 
                row__c: row,
                col__c: col,
                lay__c: lay,
                container_number__c: boxNumber, //箱号
                container_use__c: '原料',
                material_code__c: materialCode,
                material_name__c: materialName,
                specifications__c: specification,
                project_number__c: projectAttribute,
                box_number__c: Quantity, // 放入数量
                document_number__c: documentNumber, // erp单号
                operation__c: docType, // 单据类型
                picking_areas__c: '投料区', // 拣货区域

                space: spaceId,
                created: new Date(),
                created_by: userId,
                owner: userId,
            }
            await broker.call('@pc_auto_waiting__c.insert', { doc: newDoc3 });
        }







        if (projectAttr){ // 表示带有项目属性的 - 查找库中是否有相同箱子的 

            // node.warn(222);
            // 第一次 query
            let query = [['material_code__c', '=', materialCode],
                        ['material_name__c', '=', materialName],
                        ['specifications__c', '=', specification],
                        ['project_number__c', '=', projectAttr]];
            const pcMaterial = await broker.call('@pc_auto_record__c.find', { filters: [...query] });
            // node.warn(pcMaterial);


            if (pcMaterial.length) {// 表示立库中存在物料代码、规格型号、项目属性相同的箱子 - 计算属性
                // node.warn("库中存在物料代码、规格型号、项目属性相同的箱子");
                // 计算数量、要出哪个箱子和分配几个空箱
                // 分配空箱和箱号、判断库中箱子是否匹配成功
                // 如何分配：
                //      1 根据当前数量和装箱量来判断数组中哪个条件不满足
                //      2 用装箱量 - 当前数量 = 这个箱子要装几个
                //      2 到货数量 - 这个箱子要装几个 = 剩余数量(除了分配库中的还是分配多少个空箱)
                //      3 Math.ceil(剩余数量/装箱) = 表示分配几个空箱 - 向上取整
                //      3 剩余数量 % 装箱 = X个并取余(最后一个箱子放的个数)    20/40=0.5    12/5=2.4
                // node.warn(123);
                // return  

                //  先查询哪个箱子缺多少，最后计算空箱
                // // 过滤新数组
                // let earlyMaterial = pcMaterial.filter(v => v.now_number__c != QTY)
                // node.warn(earlyMaterial);

                for (let i = 0; i < pcMaterial.length; i++) {
                    if (pcMaterial[i].now_number__c < QTY){  // 当前数量 小于 装箱量
                        // const row = pcMaterial[i].row__c;
                        // node.warn(row);
                        // const col = pcMaterial[i].col__c;
                        // const lay = pcMaterial[i].lay__c;
                        const containerNumber = pcMaterial[i].container_number__c; // 箱号
                        const materialCode = pcMaterial[i].material_code__c; // 物料代码
                        const materialName = pcMaterial[i].material_name__c; // 物料名称
                        const specifications = pcMaterial[i].specifications__c; // 规格型号
                        const projectNumber = pcMaterial[i].project_number__c; // 项目编号

                        // 标记出这个箱子并计算还要几个箱子
                        const differ = QTY - pcMaterial[i].now_number__c; 
                        const surplus =  arrivalQuantity - differ;
                        // node.warn(surplus);
                        if (surplus > 0){ 
                            const emptyBox = Math.ceil(surplus / QTY);
                            // 最后一个箱子放入的数量
                            const rest = surplus % QTY;

                            // 表中查询过滤条件为emptyBox数即可
                            const rs = await broker.call('@pc_auto_status__c.find', {
                                filters: [['container_use__c', '=', '空箱'], ['container_status__c', '=', '在库']],
                                top: emptyBox,
                                sort: 'col__c asc',
                            });
                            // node.warn(rs);
                            // 1 2 3
                            if (rs.length === emptyBox){// 库中空箱数量 === 查找的空箱数
                                // 操作哪些表
                                // TODO: 1 已找到库中空箱个数
                                // TODO: 2 标记立库货架容器状态表及获取箱号 - 原料入库
                                // TODO: 3 获取立库货架容器操作记录表中要出库的箱号及要放入原料的数量
                                // TODO: 4 更新erp-数据详情表中的仓库属性为立体库
                                // TODO: 5 最终写入到立库货架-待上架原料表中erp及单号及要进行的原料放入数量及空箱个数及原料个数

                                // 1 更新erp-数据详情表
                                await broker.call('@pc_erp_data__c.update', { id, doc: { ware_attr__c: '立体库' } });

                                // 1. 原料箱子、先更新再增加
                                // 1.1 更新立库货架-容器状态表的数据 - 先查再更新
                                const findOnw = await broker.call('@pc_auto_status__c.find', { filters: [['container_number__c', '=', containerNumber]] });
                                const row = findOnw[0].row__c;
                                const col = findOnw[0].col__c;
                                const lay = findOnw[0].lay__c; 
                                await broker.call('@pc_auto_status__c.update', { id: findOnw[0]._id, doc: { container_status__c: '预占用' } });
                                // 1.2 排、列、层、箱号、项目属性、放入数量
                                addDataProject(row, col, lay, containerNumber, projectNumber, differ)

                                // 2. 空箱子
                                if(surplus > QTY){
                                    if (rest === 0) {//取余===0、// 10,10,10
                                        for (let i = 0; i < rs.length; i++) {
                                            // 1 更新空箱的状态
                                            await broker.call('@pc_auto_status__c.update', { id: rs[i]._id, doc: { container_status__c: '预占用' } });
                                            // 2 排、列、层、箱号、项目属性、放入数量
                                            addDataProject(rs[i].row__c, rs[i].col__c, rs[i].lay__c, rs[i].container_number__c, projectAttr, QTY)
                                        }
                                    } else {//取余!==0、18,18,6、前两个正常、最后一个为余数
                                        for (let i = 0; i < rs.length - 1; i++) {
                                            // 1 更新空箱的状态
                                            await broker.call('@pc_auto_status__c.update', { id: rs[i]._id, doc: { container_status__c: '预占用' } });
                                            // 2 排、列、层、箱号、项目属性、放入数量
                                            addDataProject(rs[i].row__c, rs[i].col__c, rs[i].lay__c, rs[i].container_number__c, projectAttr, QTY)
                                        }
                                        // 3 更新最后一个空箱的状态
                                        await broker.call('@pc_auto_status__c.update', { id: rs[rs.length - 1]._id, doc: { container_status__c: '预占用' } });
                                        // 4 排、列、层、箱号、项目属性、放入数量
                                        addDataProject(rs[rs.length - 1].row__c, rs[rs.length - 1].col__c, rs[rs.length - 1].lay__c, rs[rs.length - 1].container_number__c, projectAttr, rest)
                                    }
                                }else if(surplus == QTY){//放入的数量是剩余数量
                                    // 更新状态再增加
                                    await broker.call('@pc_auto_status__c.update', { id: rs[0]._id, doc: { container_status__c: '预占用' } });
                                    addDataProject(rs[0].row__c, rs[0].col__c, rs[0].lay__c, rs[0].container_number__c, projectAttr, surplus)
                                }else if(surplus < QTY){//放入箱子里面的是余数
                                    await broker.call('@pc_auto_status__c.update', { id: rs[0]._id, doc: { container_status__c: '预占用' } });
                                    addDataProject(rs[0].row__c, rs[0].col__c, rs[0].lay__c, rs[0].container_number__c, projectAttr, rest)
