async function speakText(text) {
    return new Promise((resolve, reject) => {
        exec(`powershell.exe -Command "Add-Type -AssemblyName System.Speech; $speak = New-Object System.Speech.Synthesis.SpeechSynthesizer; $speak.Rate = 0; $speak.Speak('${text}');"`, (error, stdout, stderr) => {
            if (error) {
                reject(error);
            } else {
                resolve();
            }
        });
    });
}

async function speakAllTexts(texts) {
    for (let text of texts) {
        await speakText(text);
    }
}

