    let findObj = {
        query: {}, // 查询条件
        page: 2,  // 第几页
        pageSize: 100, // 取多少条数据
        sort: {}, // 排序，按哪些字段升序或者降序，{ age: -1 }，按 age 降序
        projection: {} // 投影，只返回哪些字段
    }


    try {
        node.warn(client.topology);

        if (!client.topology || !client.topology.isConnected()) {
            node.warn("client");
            await client.connect(); // 确保连接只建立一次
        }

        const db = client.db(dbName);
        const collections = db.collection(tableName);
        // const result = await collections.find(data).toArray();

        // const page = 3;
        // const pageSize = 10;
        // const query = { age: { $gt: 18 } }; 
        // const result = await collections.find(query, { projection: { name: 1, age: 1, _id: 0 } })  // 只返回 name 和 age
        //     .sort({ age: -1 })  // 按 age 降序
        //     .skip((page - 1) * pageSize)  // 跳过前 (3-1) * 10 = 20 条
        //     .limit(pageSize)  // 取 10 条
        //     .toArray();



        let findData = null
        const { query, page, pageSize, sort } = data;
        // node.warn(data);
        node.warn(!!query);

        if (query && page && pageSize && sort) {
            findData = await collections.find(query).sort({ ...sort }).skip((page - 1) * pageSize).limit(pageSize).toArray();
        } else if (query && page && pageSize) {
            findData = await collections.find(query).skip((page - 1) * pageSize).limit(pageSize).toArray();
        } else if (query && sort) {
            findData = await collections.find(query).sort({ ...sort }).toArray();
        } else if (query) {
            findData = await collections.find(query).toArray();
        } else {
            findData = await collections.find({}).toArray();
        }

        console.log(client.topology.isConnected())

        return findData
    } catch (error) {
        // 写入到本地文件中 并 报错
