async function upDocs(tableName, id, newDoc) {
    try {
        const isObj = isObject(newDoc);
        if (isObj) {
            await client.connect();
            let db = await client.db(dbName);
            let students = await db.collection(tableName);
            let result = await students.updateOne({ _id: id }, { $set: { ...newDoc } });
            if (result.modifiedCount == 1) return true;
            else return false;
        } else { return false }
    }
    finally {
        await client.close();
    }
}

