// 代码表示： 出库任务中，出库查找相邻的两个托盘外侧的那个(不用移库)
// 如果没有相邻的两个，那么根据 排 来判断，先取2和3，后取1和4
async function findOutSidePallet() {
    let docs = await find("hs_stacker__c", { filters: [['cmdtype__c', '=', "出库任务"]] });

    // 第一遍过滤出有相邻的来开始搬运
    let firstFilter = []
    for (const item of docs) {
        if (firstFilter.length > 0) {
            break
        }
        for (const subItem of docs) {
            const faFrom = item.fromloc__c
            const roadway = +(faFrom.substring(0, 2)) // 巷道
            const row = +(faFrom.substring(2, 4)) // 排
            const lay = +(faFrom.substring(4, 6)) // 层
            const col = +(faFrom.substring(6, 8)) // 列

            const subFrom = subItem.fromloc__c
            const roadway2 = +(subFrom.substring(0, 2)) // 巷道
            const row2 = +(subFrom.substring(2, 4)) // 排
            const lay2 = +(subFrom.substring(4, 6)) // 层
            const col2 = +(subFrom.substring(6, 8)) // 列


            if (roadway === roadway2 && lay === lay2 && col === col2 && item._id != subItem._id) {
                // 临近的两个
                // 一排(内侧)相邻的二排(外侧)
                if ((row === 1 && row2 === 2) || (row === 4 && row2 === 3)) {
                    // node.warn(subItem);
                    firstFilter.push(subItem)
                    break
                }
            }
        }
    }

    if (firstFilter.length > 0) {
        // 找到相邻的两个托盘(是外侧的)
        return firstFilter[0]
    }
    else {

    }
}


