// 根据 `巷道` 升序 &&  `排` 按照 2314 这么排列 
const sortOrder = { '01': 3, '02': 1, '03': 2, '04': 4 };
const newData = data.sort((a, b) => {
    const dateA = new Date(a.date);
    const dateB = new Date(b.date);

    let dateF1 = dateA < dateB
    let dateF2 = dateA > dateB
    let productF1 = a.product__c < b.product__c
    let productF2 = a.product__c > b.product__c

    // 先根据物料名去排序、如果物料名相同、根据日期去排序、如果日期相同、根据fromloc去做处理
    if (productF1) {
        return -1;
    }
    else if (productF2) {
        return 1;
    }
    else {
        if (dateF1) {
            return -1;
        }
        else if (dateF2) {
            return 1;
        }
        else { 
            const compareRoadway = Number(a.fromloc.substring(0, 2)) - Number(b.fromloc.substring(0, 2)); // 巷道
            const compareRow = sortOrder[a.fromloc.substring(2, 4)] - sortOrder[b.fromloc.substring(2, 4)]; // 排
            const compareCol = Number(a.fromloc.substring(6, 8)) - Number(b.fromloc.substring(6, 8)); // 列

            if (compareCol !== 0) {
                return compareCol;
            } else if (compareRoadway !== 0) {
                return compareRoadway;
            } else if (compareRow !== 0) {
                return compareRow
            }
            return 0;
        }
    }
});
