const data = await find("hs_ewm_out__c", { filters: [['status__c', '=', '未执行']] }); 
if(data.length){
    for (const item of data) {
        if (item.qty__c && item.reserved2__c !== "" && item.source__c !== ""){
            let source = item.source__c;  
            const lane = +(source.substring(0, 2));
            const row = +(source.substring(2, 4));
            const lay = +(source.substring(4, 6));
            const col = +(source.substring(6, 8));
            let palletRes = await find("hs_pallet_detail__c", { filters: [['lane__c', '=', lane], ['row__c', '=', row], ['lay__c', '=', lay], ['col__c', '=', col], ] })
            // node.warn(palletRes[0]);
            // 在托盘详情数据找到该托盘
            if (palletRes.length){
                if (palletRes.length === 1){
                    let finiallyLoc = "";
                    const type = item.reserved2__c;
                    if (type === "XO02") { finiallyLoc = "" } else {
                        const zone = palletRes[0].use__c; // 判断库存中的托盘区域
                        if (zone === "包材区域") finiallyLoc = "1047";
                        if (zone === "成品区域") {
                            const value = Math.floor(Math.random() * 3); // 0,1,2,3
                            let locLoc = { 0: "1090", 1: "1092", 2: "1094" }
                            finiallyLoc = locLoc[value]
                        }
                    }
                    // EWM传递相同库位时，如果正在出库，那么再传递数量要直接扣减，不需要出库任务
                    if (finiallyLoc) {
                        const ewmQTY = item.qty__c; // EWM传递的数量
                        const storeQTY = palletRes[0].qty__c; // 当前数量
                        const lastQTY = palletRes[0].last_qty__c; // 最终数量
                        const allQTY = lastQTY - ewmQTY; // 在库数量 - EWM  = 最终数量    大于：100-80   等于：100-100   小于：100-200
                        const handleQTY = +((allQTY).toFixed(3)); 
                        const status = palletRes[0].status__c; // 处理托盘状态：在库、正在出库、已出库


                        async function common() { 
                            const time = global.get("time")()
                            const taskNo = global.get("taskNo")()
                            const pallet = palletRes[0].pallet__c;
                            const detail = await ins("hs_pallet_info__c", {
                                name: "查看详情",
                                time__c: time,
                                task_type__c: "出库任务",
                                pallet__c: pallet,
                                taskno__c: taskNo,
                                step1__c: "任务已创建"
                            })
                            await ins("hs_task__c", {
                                name: "步骤壹",
                                time__c: time,
                                pallet__c: pallet,
                                taskno__c: taskNo,
                                curr_loc__c: `${source}`,
                                fromloc__c: `${source}`,
                                nextloc__c: finiallyLoc,
                                product__c: "",
                                priority__c: 1,
                                is_manual__c: "否",
                                work_type__c: "搬运任务",
                                task_source__c: "上位自动",
                                task_type__c: "出库任务",
                                detail_info__c: detail._id, // 位置详情，iD关联 
                            })
                            let stra = {
                                1: "一号堆垛机",
                                2: "二号堆垛机",
                                3: "三号堆垛机",
                                4: "四号堆垛机",
                            }
                            await ins("hs_stacker__c", {
                                time__c: time,
                                stacker__c: stra[lane],
                                pallet__c: pallet,
                                taskno__c: taskNo,
                                product__c: "1",
                                fromloc__c: source,
                                nextloc__c: finiallyLoc,
                                cmdtype__c: "出库任务",
                                type_scurce__c: "上位自动",
                                priority__c: Number(1), // 优先级
                                status__c: "未执行",
                                remove__c: "无" // 移库分解动作
                            }) 
                        }

                        if (status === "在库"){
                            if (handleQTY == 0) { 
                                if (row === 2 || row === 3) {
                                    await common() 
                                }else{
                                    new Promise((reslove, reject) => {
                                        setTimeout(async () => {
                                            await common() 
                                        }, 2000)
                                    })
                                }
                                await up("hs_pallet_detail__c", palletRes[0]._id, { last_qty__c: handleQTY, status__c: "正在出库" });
                                await up("hs_ewm_out__c", item._id, { status__c: "执行成功", desc__c: "" });
                            }
                            if (handleQTY > 0) { 
                                if (row === 2 || row === 3) {
                                    await common()
                                } else {
                                    new Promise((reslove, reject) => {
                                        setTimeout(async () => {
                                            await common()
                                        }, 2000)
                                    })
                                }
                                await up("hs_pallet_detail__c", palletRes[0]._id, { last_qty__c: handleQTY, status__c: "正在出库" });
                                await up("hs_ewm_out__c", item._id, { status__c: "执行成功", desc__c: "" });
                            }
                            if (handleQTY < 0) {
                                await up("hs_ewm_out__c", item._id, { status__c: "执行失败", desc__c: "EWM传递的数量大于库中的数量" });
                            } 
                        }
                        if (status === "正在出库") { // 只需要减数量
                            if (handleQTY == 0) { 
                                await up("hs_pallet_detail__c", palletRes[0]._id, { last_qty__c: handleQTY });
                                await up("hs_ewm_out__c", item._id, { status__c: "执行成功", desc__c: "" });
                            }
                            if (handleQTY > 0) { 
                                await up("hs_pallet_detail__c", palletRes[0]._id, { last_qty__c: handleQTY });
                                await up("hs_ewm_out__c", item._id, { status__c: "执行成功", desc__c: "" });
                            }
                            if (handleQTY < 0) {
                                await up("hs_ewm_out__c", item._id, { status__c: "执行失败", desc__c: "EWM传递的数量大于库中的数量" });
                            }
                        }
                        if (status === "已出库") { // 直接更新EWM出库任务错误、错误类型为该托盘已出库
                            await up("hs_ewm_out__c", item._id, { status__c: "执行失败", desc__c: "该托盘已出库，无法减数量" });
                        }
                    } else { 
                        await up("hs_ewm_out__c", item._id, { status__c: "执行失败", desc__c: "根据出库标识或货位信息未找到出口" });
                    }
                }else{
                    await up("hs_ewm_out__c", item._id, { status__c: "执行失败", desc__c: "托盘详情信息中找到的托盘不为一" });
                }
            }else{ 
                await up("hs_ewm_out__c", item._id, { status__c: "执行失败", desc__c: "该仓位信息在库中不存在" });
            }
        }else{ 
            await up("hs_ewm_out__c", item._id, { status__c: "执行失败", desc__c: "数据缺少：数量、出库标识、仓位信息" });
        }
    }
}

