                                            }, 2000)
                                        })
                                        return null
                                    }  // 执行其他
                                } // 执行其他 
                            } else {
                                return await taskOut() // 1和4排 出库无阻挡
                            }
                        } else {
                            return await taskOut() // 2和3排 直接出库
                        }
                    }
                }
            }
        }

        const endTime = new Date() 
        const timess = +(endTime) - +(start)
        node.warn(`For循环执行了： ${alltimess} 次`);
        // node.warn(`For内循环： ${allTi} 次`);
        node.warn(`${timess / 1000} 秒`);
    } 
