                        return null
                    }
                }
            } else {
                await up(tableName, fDocs[0]._id, { status__c: "执行失败", desc__c: "根据该物料代码未找到分配区域" })
                // ApplicationInfo("EWM入库任务中：此托盘在EWM入库任务中 根据该物料代码未找到分配区域")
                // return [{ payload: 1 }]
                up("hs_task__c", applyTask[0]._id, { name: "获取任务失败", desc__c: "EWM入库任务中：此托盘在EWM入库任务中 根据该物料代码未找到分配区域" })

                return null
            }
        } else {
            await up(tableName, fDocs[0]._id, { status__c: "执行失败", desc__c: "自动任务失败，缺少物料代码，批号，生产日期中的一项" })
            // ApplicationInfo("EWM入库任务中：此托盘在EWM入库任务中 缺少物料代码，批号，生产日期中的一项")
            // return [{ payload: 1 }]
            up("hs_task__c", applyTask[0]._id, { name: "获取任务失败", desc__c: "EWM入库任务中：此托盘在EWM入库任务中 缺少物料代码，批号，生产日期中的一项" })
            return null
        }
    }



    const docs = await find("hs_create_task__c", { filters: [['type__c', '=', '入库任务'], ['location__c', '=', String(location)], ['status__c', '=', "未执行"]] });
    if (docs && docs.length === 1) {
        if (isPallet.length) {
            await up("hs_create_task__c", docs[0]._id, { time__c: global.get('time')(), status__c: "执行失败", desc__c: `立库中存在此托盘号 ${pallet}` })
            // ApplicationInfo(`手动任务中：立库中存在此托盘号 ${pallet}`)
            // return [{ payload: 1 }]
            up("hs_task__c", applyTask[0]._id, { name: "获取任务失败", desc__c: `手动任务中：立库中存在此托盘号 ${pallet}` })
            return null
        }

        const { location__c, dealer_name__c, number__c, doc__c, material_type__c } = docs[0];

        let result = []
        let isRun = false
        let allLoc = await find("hs_ware_loc__c")
        if (material_type__c === "手动物料区域") {
            if (location__c && dealer_name__c && number__c) {
                result = allLoc.filter(value => {
                    let f1 = value.dealer_name__c == dealer_name__c;
                    let f2 = value.number__c == number__c;
                    let f3 = value.doc__c == doc__c;
                    return f1 && f2 && f3
                })
                isRun = true
            } else {
                isRun = false
                await up("hs_create_task__c", docs[0]._id, { time__c: global.get('time')(), status__c: "执行失败", desc__c: "请重新创建，缺少经销商名、数量、交货单号中的一项，删除重建" })
                // ApplicationInfo(`手动任务中：手动物料区域 缺少经销商名、数量、交货单号中的一项，删除重建`)
                // return [{ payload: 1 }]
                up("hs_task__c", applyTask[0]._id, { name: "获取任务失败", desc__c: `手动任务中：手动物料区域 缺少经销商名、数量、交货单号中的一项，删除重建` })
                return null
            }
        }
        if (material_type__c === "手动空托盘区域") {
            if (location__c && number__c) {
                result = allLoc.filter(value => {
                    return value.use__c === "手动空托盘区域"
                })
                isRun = true
            } else {
                isRun = false
                await up("hs_create_task__c", docs[0]._id, { time__c: global.get('time')(), status__c: "执行失败", desc__c: "缺少起始位置或数量" })
                // ApplicationInfo(`手动任务中：手动空托盘区域 缺少起始位置或数量`)
                // return [{ payload: 1 }]
                up("hs_task__c", applyTask[0]._id, { name: "获取任务失败", desc__c: `手动任务中：手动空托盘区域 缺少起始位置或数量` })
                return null
            }
        }

        if (isRun) {
            let isEmptyLoc = []
            if (result.length) {
                const findLoc = (findLoc) => allLoc.filter(value => value.loc__c === findLoc && value.status__c == "空闲")
                for (let i = 0; i < result.length; i++) {
                    const { lane__c, row__c, col__c, lay__c } = result[i];
                    // use原料：查找出相邻的位置是否可以放货 
                    let rowObj = {
                        1: findLoc(`0${lane__c}020${lay__c}${col__c >= 10 ? col__c : "0" + col__c}`), // 1排，找隔壁2排 是否为空 可以放货
                        2: findLoc(`0${lane__c}010${lay__c}${col__c >= 10 ? col__c : "0" + col__c}`), // 2排，找隔壁1排 是否为空 可以放货
                        3: findLoc(`0${lane__c}040${lay__c}${col__c >= 10 ? col__c : "0" + col__c}`), // 3排，找隔壁4排 是否为空 可以放货
                        4: findLoc(`0${lane__c}030${lay__c}${col__c >= 10 ? col__c : "0" + col__c}`), // 4排，找隔壁3排 是否为空 可以放货
                    }
                    const res = rowObj[row__c];
                    if (res.length) {
                        isEmptyLoc.push(res[0])
                        break
                    }
                }
            }
            // 四、创建 托盘运行状态详情
            // 一、创建 出入库总任务
            // 二、更新 手动任务表
            // 三、更新 仓库货位管理 货位状态预占用、托盘号信息
            // 六、返回PLC信号
            async function ExecTask(data) {
                const time = global.get('time')()
                // const pallet = global.get('pallet')()  // 拿真实托盘代替
                const taskno = global.get('taskNo')()
                const { lane__c, row__c, col__c, lay__c } = data;
                const dest = `0${lane__c}0${row__c}0${lay__c}${col__c >= 10 ? col__c : "0" + col__c}`
                // ins("hs_pallet_info__c", {
                //     name: "查看详情",
                //     time__c: time,
                //     task_type__c: "入库任务",
                //     pallet__c: pallet,
                //     taskno__c: taskno,
                //     step1__c: "任务已创建"
                // })
                up("hs_task__c", applyTask[0]._id, {
                    name: "步骤一",
                    time__c: time,
                    pallet__c: pallet,
                    taskno__c: taskno,
                    curr_loc__c: `${location}`,
                    fromloc__c: `${location}`,
                    nextloc__c: dest,
                    product__c: "",
                    priority__c: priority,
                    is_manual__c: "是",
                    work_type__c: "搬运任务",
                    task_source__c: "WCS手动",
                    task_type__c: "入库任务",
                    // detail_info__c: detail._id, // 位置详情，iD关联 
                })
                // 更新手动任务
                up("hs_create_task__c", docs[0]._id, {
                    time__c: time,
                    pallet__c: pallet,
                    taskno__c: taskno,
                    status__c: "执行成功",
                    desc__c: ""
                })
                if (material_type__c === "手动物料区域") {
                    // 更新仓库货位管理
                    up("hs_ware_loc__c", data._id, {
                        pallet__c: pallet,
                        status__c: "预占用",
                        dealer_name__c: dealer_name__c,
                        number__c: number__c,
                        doc__c: doc__c,
                        // use__c: "手动区域",
                        use__c: material_type__c
                    })
                }
                if (material_type__c === "手动空托盘区域") {
                    up("hs_ware_loc__c", data._id, {
                        pallet__c: pallet,
                        status__c: "预占用",
                        // dealer_name__c: dealer_name__c,
                        number__c: number__c,
                        // doc__c: doc__c,
                        // use__c: "手动区域",
                        use__c: material_type__c
                    })
                }

                return [{ payload: 1 }]
            }
            const stackerOpen = await find("hs_stacker_is_open__c")
            let isEmp = false
            if (isEmptyLoc.length > 0) {
                const laneNum = +(isEmptyLoc[0].lane__c)
                const findStacker = stackerOpen.filter(v => v.lane_num__c == laneNum);
                if (findStacker.length > 0) {
                    if (findStacker[0].is_open__c == 1) {
                        isEmp = true
                    } else {
                        isEmp = false
                    }
                } else {
                    isEmp = false
                }
            }
            // ！表示有相同的物料，并且相邻的库位可以放货
            if (isEmp) {
                return await ExecTask(isEmptyLoc[0])
            } else {
                let product = await find("hs_rule__c", { filters: [['product__c', '=', material_type__c]] })
                if (product && product.length) {
                    let allStorage = []
                    for (let index = 0; index < product.length; index++) {
                        const element = product[index];
                        const findStacker = stackerOpen.filter(v => v.lane_num__c == element.lane__c);
                        if (findStacker.length > 0) {
                            if (findStacker[0].is_open__c == 1) { // 表示堆垛机开启
                                let findStore = allLoc.filter(v => {
                                    let f1 = v.lane__c == element.lane__c; // 一巷道
                                    let f2 = v.row__c >= 1 && v.row__c <= 4; // 一 到 四 排
                                    let f3 = v.lay__c >= element.lay__c && v.lay__c <= element.to_lay__c;
                                    let f4 = v.col__c >= element.col__c && v.col__c <= element.to_col__c;
                                    let f5 = v.status__c === "空闲"
                                    return f1 && f2 && f3 && f4 && f5
                                })
                                allStorage.push(...findStore)
                            }
                        }

                    }
                    allStorage.sort((a, b) => {
                        let lay1 = a.lay__c < b.lay__c; // 层升序
                        let lay2 = a.lay__c > b.lay__c;

                        let col1 = a.col__c < b.col__c; // 列升序
                        let col2 = a.col__c > b.col__c;

                        let lane1 = a.lane__c < b.lane__c; // 巷道升序
                        let lane2 = a.lane__c > b.lane__c;

                        let row1 = a.row__c < b.row__c;
                        let row2 = a.row__c > b.row__c;

                        if (lay1) return -1;
                        else if (lay2) return 1;
                        else {
                            if (col1) return -1;
                            else if (col2) return 1;
                            else {
                                if (row1) return -1;
                                else if (row2) return 1;
                                else {
                                    if (lane1) return -1;
                                    else if (lane2) return 1;
                                    else return 0;
                                }
                            }
                        }
                    })
                    if (allStorage && allStorage.length > 0) {
                        const findLoc = (findLoc) => allLoc.filter(value => value.loc__c === findLoc && value.status__c == "空闲")
                        for (let index = 0; index < allStorage.length; index++) {
                            const element = allStorage[index];
                            const { lane__c, row__c, col__c, lay__c, } = element; // 按顺序找到的每一个货位  
                            let rowObj = {
                                1: findLoc(`0${lane__c}020${lay__c}${col__c >= 10 ? col__c : "0" + col__c}`), // 1排，找隔壁2排 是否为空 可以放货
                                2: findLoc(`0${lane__c}010${lay__c}${col__c >= 10 ? col__c : "0" + col__c}`), // 2排，找隔壁1排 是否为空 可以放货
                                3: findLoc(`0${lane__c}040${lay__c}${col__c >= 10 ? col__c : "0" + col__c}`), // 3排，找隔壁4排 是否为空 可以放货
                                4: findLoc(`0${lane__c}030${lay__c}${col__c >= 10 ? col__c : "0" + col__c}`), // 4排，找隔壁3排 是否为空 可以放货
                            }
                            const result = rowObj[row__c]; // 要获取返回值：判断是 里侧还是外侧
                            if (result.length > 0) {
                                // x x | x x  都是空 （直接分）
                                if (row__c === 1) {
                                    // console.log('一排', element)
                                    return await ExecTask(element)
                                }
                                // o o | x x  都是空 （分给四排，三排作为补）
                                if (row__c === 3) {
                                    // console.log('三排', result[0]) // 三排临近为空，是入库，所以库位分给四排 （分内侧）
                                    return await ExecTask(result[0])
                                }
                                break
                            }
                        }
                        await up("hs_create_task__c", docs[0]._id, { time__c: global.get('time')(), status__c: "执行失败", desc__c: "手动区域无货位了" })
                        // ApplicationInfo(`手动任务中：请重新创建，手动区域无货位了`)
                        // return [{ payload: 1 }]
                        up("hs_task__c", applyTask[0]._id, { name: "获取任务失败", desc__c: `手动区域无货位了` })
                        return null
                    } else {
                        await up("hs_create_task__c", docs[0]._id, { time__c: global.get('time')(), status__c: "执行失败", desc__c: "请重新创建，手动区域无货位了" })
                        // ApplicationInfo(`手动任务中：请重新创建，手动区域无货位了`)
                        // return [{ payload: 1 }]
                        up("hs_task__c", applyTask[0]._id, { name: "获取任务失败", desc__c: `手动任务中：请重新创建，手动区域无货位了` })
                        return null
                    }
                } else {
                    // 未找到手动分配规则
                    await up("hs_create_task__c", docs[0]._id, { time__c: global.get('time')(), status__c: "执行失败", desc__c: "请重新创建，未找到手动分配规则" })
                    // ApplicationInfo(`手动任务中：请重新创建，未找到手动分配规则`)
                    // return [{ payload: 1 }]
                    up("hs_task__c", applyTask[0]._id, { name: "获取任务失败", desc__c: `手动任务中：请重新创建，未找到手动分配规则` })
                    return null
                }


            }
        } else {
            await up("hs_create_task__c", docs[0]._id, { time__c: global.get('time')(), status__c: "执行失败", desc__c: "任务异常" })
            // ApplicationInfo(`手动任务中：手动空托盘区域 缺少起始位置或数量`)
            // return [{ payload: 1 }]
            up("hs_task__c", applyTask[0]._id, { name: "获取任务失败", desc__c: `手动任务中：任务异常` })
            return null
        }
    } else if (docs && docs.length > 1) {
        for (const item of docs) {
            await up("hs_create_task__c", item._id, { time__c: global.get('time')(), status__c: "执行失败", desc__c: "请重新创建，任务重复，不要一次创建多条" })
        }
        // ApplicationInfo(`手动任务中：请重新创建，任务重复，不要一次创建多条`)
        // return [{ payload: 1 }]
        up("hs_task__c", applyTask[0]._id, { name: "获取任务失败", desc__c: `手动任务中：请重新创建，任务重复，不要一次创建多条` })
        return null
    }





    up("hs_task__c", applyTask[0]._id, { name: "获取任务失败", desc__c: "未找到任务，请重新入库申请" })
}

