1. 基本查询：   
    const query = { name: "张三" }; // 查询 name 等于 "张三" 的文档
    let QUERY = { "stackers__c": "二号堆垛机", "task_code__c": "4106257", "priority__c": 1 };

2. 使用比较运算符
    $eq	等于	{ age: { $eq: 25 } }
    $ne	不等于	{ age: { $ne: 18 } }
    $gt	大于	{ age: { $gt: 18 } }
    $gte大于等于	{ age: { $gte: 18 } }
    $lt	小于	{ age: { $lt: 30 } }
    $lte小于等于	{ age: { $lte: 30 } }
    示例：查询 age 大于等于 18 的用户      const query = { age: { $gte: 18 } };
    示例：查询 score 在 60 - 100 之间的用户   const query = { score: { $gte: 60, $lte: 100 } };

3. 使用 $in 和 $nin
    $in	值在列表中	{ city: { $in: ["北京", "上海", "广州"] } }
    $nin	值不在列表中	{ status: { $nin: ["已删除", "冻结"] } }
    ✅ 示例：查询 city 在 ["北京", "上海", "广州"] 里面的用户：  const query = { city: { $in: ["北京", "上海", "广州"] } };
    ✅ 示例：查询 status 不是 ["已删除", "冻结"] 的用户：   const query = { status: { $nin: ["已删除", "冻结"] } };

4. 模糊查询（正则匹配）
    运算符	含义	示例
    $regex	正则匹配	{ name: { $regex: "张" } }
    ✅ 示例：查询 name 包含 "张" 的用户：   const query = { name: { $regex: "张" } };
    ✅ 示例：查询 email 以 "@gmail.com" 结尾的用户：    const query = { email: { $regex: "@gmail\\.com$" } };

5. 逻辑运算
    运算符	含义	示例
    $and	同时满足多个条件	{ $and: [{ age: { $gte: 18 } }, { city: "上海" }] }
    $or	满足任意一个条件	{ $or: [{ age: { $lt: 18 } }, { city: "北京" }] }
    $not	取反	{ age: { $not: { $gt: 18 } } }
    ✅ 示例：查询 age 大于 18 且 city 是 "上海" 的用户：    const query = { $and: [{ age: { $gt: 18 } }, { city: "上海" }] };
    ✅ 示例：查询 age 小于 18 或 city 是 "北京" 的用户：    const query = { $or: [{ age: { $lt: 18 } }, { city: "北京" }] };

6. 查询数组
    运算符	含义	示例
    $all	数组包含所有指定值	{ tags: { $all: ["运动", "科技"] } }
    $size	数组长度	{ tags: { $size: 2 } }
    $elemMatch	数组中的元素匹配	{ scores: { $elemMatch: { $gte: 90 } } }
    ✅ 示例：查询 tags 包含 "运动" 和 "科技" 的文档：   const query = { tags: { $all: ["运动", "科技"] } };
    ✅ 示例：查询 scores 数组中有大于 90 分的文档：     const query = { scores: { $elemMatch: { $gte: 90 } } };
    ✅ 示例：查询 tags 数组长度为 2 的文档：    const query = { tags: { $size: 2 } };

7. 查询 null 和 exists
    运算符	含义	示例
    null	查询字段值为 null	{ email: null }
    $exists	查询字段是否存在	{ phone: { $exists: true } }
    ✅ 示例：查询 email 为空的用户：    const query = { email: null };
    ✅ 示例：查询 phone 字段存在的用户：    const query = { phone: { $exists: true } };

