async function transactionExample() {
    const userId = "user:1001";

    const balance = await redis.get(userId);
    if (parseInt(balance) >= 50) {
        const multi = redis.multi();
        multi.decrby(userId, 50); // 扣款
        multi.set("order:123", "paid");
        await multi.exec();
        console.log("支付成功");
    } else {
        console.log("余额不足");
    }
}

transactionExample();
