const redis = global.get("redis")



// 📌 场景：电商秒杀时，防止多个用户同时购买超出库存。

async function distributedLockExample() {
    const lockKey = "product_lock";
    const lockValue = "unique_value_" + Date.now();
    const lock = await redis.set(lockKey, lockValue, "NX", "EX", 10); // 10秒自动释放

    if (lock) {
        console.log("获得锁，开始执行任务...");
        await new Promise((resolve) => setTimeout(resolve, 2000)); // 模拟任务
        if ((await redis.get(lockKey)) === lockValue) {
            await redis.del(lockKey);
            console.log("任务完成，释放锁");
        }
    } else {
        console.log("未获取到锁，任务被其他进程执行");
    }
}

distributedLockExample();
