// 如果是出库任务，判断修改时间是否超过10秒，防止两个任务一起时，先执行内侧的任务


if (msg.payload['getRunMode'] === 5 && msg.payload['getStatus'] === 0) {
    let [ins, del, up, find] = global.get(['insDocs', 'delDocs', 'upDocs', 'findDocs']);

    const results = await find("hs_stacker__c", { filters: [['stacker__c', '=', stacker]], sort: "priority__c desc, time__c asc" })
    if (!results.length) return;
    if (results.some(value => value.status__c === "正在执行")) return; // 状态：未执行(1)  正在执行(2)  已完成(3)

    const stackerOpen = await find("hs_stacker_is_open__c", { filters: [['stacker_name__c', '=', stacker]] });
    if (stackerOpen.length && stackerOpen[0].is_open__c == 0) return

    const fDocs = results.filter(value => value.status__c === "未执行"); // 获取所有未执行的列表数据

    // 未执行 正在进行中的任务
    if (fDocs.length > 0) {
        let time = global.get('time');

        let [inStock, outStock] = global.get(['inStock', 'outStock'])

        let ku1 = ((global.get("ku1")) && (global.get("ku1"))[`sendIsPallet${out1}`])

        let ku2 = ((global.get("ku2")) && (global.get("ku2"))[`sendIsPallet${out2}`])

        let ku3 = ((global.get("ku3")) && (global.get("ku3"))[`sendIsPallet${out3}`])
        // node.warn(ku3);

        const allLoc = await find("hs_ware_loc__c")



        for (let index = 0; index < fDocs.length; index++) {
            const item = fDocs[index];

            const plctask = String(parseInt((Math.random() * 9999999999999))).substring(0, 11);
            const { _id, stacker__c, pallet__c, taskno__c, product__c, fromloc__c, nextloc__c, cmdtype__c } = item;


            // ================= 移库 ==================== 
            if (cmdtype__c === "移库任务") {
                if (item.remove__c === "移库分解三") {
                    const isReove = fDocs.some(v => v.remove__c === "移库分解二")
                    if (!isReove) {
                        let point = fromloc__c.length > 5 && nextloc__c.length > 5;
                        let nextLength = nextloc__c.substring(0, 2) === nextloc__c.substring(0, 2);
                        if (point && nextLength) {
                            await up("hs_stacker__c", _id, { status__c: "正在执行", run_create_time__c: new Date() });
                            const mvStock = global.get("mvStock")
                            return mvStock(pallet__c, plctask, product__c, fromloc__c, nextloc__c);
                        }
                    }
                } else {
                    let point = fromloc__c.length > 5 && nextloc__c.length > 5;
                    let nextLength = nextloc__c.substring(0, 2) === nextloc__c.substring(0, 2);
                    if (point && nextLength) {
                        const total = await find("hs_task__c", { filters: [['pallet__c', '=', pallet__c]] });
                        if (total.length) {
                            await up("hs_stacker__c", _id, { status__c: "正在执行", run_create_time__c: new Date() });
                            await ins("hs_mutual_stacker__c", { ...total[0], ...item, _id: null, time__c: time(), desc_info__c: "已下发堆垛机托盘号、起点、终点" });
                            const mvStock = global.get("mvStock")
                            return mvStock(pallet__c, plctask, product__c, fromloc__c, nextloc__c);
                        }
                    }
                }
            }


            // ================= 入库 ====================
            if (cmdtype__c === "入库任务") {
                if (['1002', '1049', '1113'].includes(fromloc__c) && nextloc__c.length > 5) {
                    const total = await find("hs_task__c", { filters: [['name', '=', '步骤六'], ['pallet__c', '=', pallet__c]], sort: "time__c desc" });
                    if (total.length) {
                        async function Task() {
                            // const total = await find("hs_task__c", { filters: [['name', '=', '步骤六'], ['pallet__c', '=', pallet__c]] });
                            if (total.length) {
                                await up("hs_stacker__c", _id, { status__c: "正在执行", run_create_time__c: new Date() });
                                await up("hs_task__c", total[0]._id, { name: "步骤七", curr_loc__c: `${stacker} 正在入库` })
                                const palletInfo = await find("hs_pallet_info__c", { filters: [['pallet__c', '=', pallet__c], ['taskno__c', '=', taskno__c]], });
                                if (palletInfo.length) await up("hs_pallet_info__c", palletInfo[0]._id, { step7__c: `${stacker} 正在搬运任务` })
                                await ins("hs_mutual_stacker__c", { ...total[0], ...item, _id: null, time__c: time(), desc_info__c: "已下发堆垛机托盘号、起点、终点" });
                                if (fromloc__c === "1049") {
                                    return inStock(pallet__c, plctask, product__c, 3, 1, 1, nextloc__c); // 判断起点, 抛终点即可
                                }
                                if (fromloc__c === "1002") {
                                    return inStock(pallet__c, plctask, product__c, 2, 1, 72, nextloc__c); // 判断起点, 抛终点即可
                                }
                                if (fromloc__c === "1113") {
                                    return inStock(pallet__c, plctask, product__c, 3, 4, 1, nextloc__c); // 判断起点, 抛终点即可
                                }
                            } else return []
                        }

                        const rowLoc = nextloc__c.substring(2, 4); // 排
                        // 入库巷道是 O x | x x 
                        if (rowLoc === "01" || rowLoc === "04") {
                            let findRow = 0;
                            if (rowLoc === "01") findRow = 2;
                            if (rowLoc === "04") findRow = 3;
                            const findLoc = (lane__c, col__c, lay__c, findRow) => allLoc.filter(v2 => v2.row__c === findRow && v2.status__c === "占用" && v2.lane__c === lane__c && v2.col__c === col__c && v2.lay__c === lay__c)
                            const lane = Number(nextloc__c.substring(0, 2)); // 获取巷道
                            const lay = Number(nextloc__c.substring(4, 6)) // 层
                            const col = Number(nextloc__c.substring(6, 8)) // 列
                            const res = findLoc(lane, col, lay, findRow)

                            if (res && res.length) {
                                node.warn("入库移库");
                                const task = await find("hs_stacker__c", { filters: [['stacker__c', '=', stacker], ['type_scurce__c', '=', "移库任务"], ['status__c', '!=', '已完成']] })
                                if (task.length) {
                                    return []
                                }

                                // 1排出库时，2排阻挡  需要移库
                                async function CommonStackers(data, cmdtype, fromloc, nextloc, typeScource, priority, remove) {
                                    let doc = {
                                        time__c: time(),
                                        stacker__c: stacker,
                                        pallet__c: data.pallet__c,
                                        taskno__c: global.get('taskNo')(),
                                        product__c: data.product__c,
                                        fromloc__c: fromloc,
                                        nextloc__c: nextloc,
                                        cmdtype__c: cmdtype,
                                        type_scurce__c: typeScource, // 搬运任务
                                        priority__c: +(priority), // 优先级
                                        status__c: "未执行",
                                        remove__c: remove
                                    }
                                    await ins("hs_stacker__c", doc)
                                }
                                const { lane__c, row__c, col__c, lay__c } = res[0];
                                let column = 0;
                                if (col__c >= 1 && col__c <= 20) { column = 20 }
                                if (col__c > 20 && col__c < 60) { column = 40 }
                                if (col__c >= 60 && col__c <= 72) { column = 60 }
                                let fromLOC = `0${lane__c}0${row__c}0${lay__c}${col__c >= 10 ? col__c : "0" + col__c}`;
                                let destLOC = `0${lane__c}0201${column}` // x巷道2排1层 x列
                                await CommonStackers(item, "移库任务", fromLOC, destLOC, "移库任务", 13, "移库分解一") // 阻挡位 到 暂存位
                                new Promise((reslove, reject) => {
                                    setTimeout(async () => {
                                        await up("hs_stacker__c", item._id, { priority__c: 12, type_scurce__c: "移库任务", remove__c: "移库分解二" });
                                        await CommonStackers(item, "移库任务", destLOC, fromLOC, "移库任务", 11, "移库分解三") // 暂存位 到 阻挡位 
                                    }, 3000)
                                })
                                return []
                            } else {
                                return await Task()
                            }
                        } else {
                            return await Task()
                        }

                    }


                }
            }





            if (cmdtype__c === "出库任务") {
                // for (const item2 of results) {
                //     if (item2.cmdtype__c === "出库任务") {
                //         if ((+(new Date()) - +(new Date(item2.created))) < 5000) return
                //     }
                // }
                const sortOrder = { '01': 3, '02': 1, '03': 2, '04': 4 };
                const newData = fDocs.filter(v => v.cmdtype__c === "出库任务").sort((a, b) => {
                    const priorityF1 = a.priority__c < b.priority__c;
                    const priorityF2 = a.priority__c > b.priority__c;
                    const as = a.fromloc__c;
                    const bs = b.fromloc__c;
                    const compareRoadway = Number(as.substring(0, 2)) - Number(bs.substring(0, 2)); // 巷道
                    const compareRow = sortOrder[as.substring(2, 4)] - sortOrder[bs.substring(2, 4)]; // 排
                    const compareCol = Number(as.substring(6, 8)) - Number(bs.substring(6, 8)); // 列 
                    // 先根据物料名去排序、如果物料名相同、根据日期去排序、如果日期相同、根据fromloc去做处理
                    if (priorityF2) { return -1; }
                    else if (priorityF1) { return 1; }
                    else {
                        if (compareRow !== 0) {
                            return compareRow
                        }
                        return 0;
                    }
                });
                // 出来 总任务 和 堆垛机数据
                async function TaskOut(data) {
                    node.warn(data);
                    const total = await global.get("findDocs")("hs_task__c", { filters: [['name', '=', '步骤壹'], ['pallet__c', '=', data.pallet__c]] })
                    // const total = await find("hs_task__c", { filters: [['name', '=', '步骤壹'], ['pallet__c', '=', data.pallet__c]] });
                    node.warn(total);
                    if (total.length) {
                        const plctasks = String(parseInt((Math.random() * 9999999999999))).substring(0, 11);
                        await up("hs_stacker__c", data._id, { status__c: "正在执行", run_create_time__c: new Date() });
                        await up("hs_task__c", total[0]._id, { name: "步骤贰", curr_loc__c: `${stacker} 正在出库` })

                        const palletInfo = await find("hs_pallet_info__c", { filters: [['pallet__c', '=', data.pallet__c], ['taskno__c', '=', data.taskno__c]], });
                        if (palletInfo.length) await up("hs_pallet_info__c", palletInfo[0]._id, { step2__c: `已下发 ${stacker} 托盘号、起点、终点` })

                        await ins("hs_mutual_stacker__c", { ...total[0], ...item, _id: null, time__c: time(), desc_info__c: "已下发堆垛机托盘号、起点、终点" });
                        let result = []
                        if (['1047'].includes(data.nextloc__c)) {
                            result = outStock(data.pallet__c, plctasks, 1, data.fromloc__c, 3, 1, 72); // 判断起点, 抛终点即可
                        }
                        if (['1090', '1092', '1094'].includes(data.nextloc__c)) {
                            result = outStock(data.pallet__c, plctasks, 1, data.fromloc__c, 2, 1, 1); // 判断起点, 抛终点即可
                        }
                        if (['1121', '1135', '1140'].includes(data.nextloc__c)) {
                            result = outStock(data.pallet__c, plctasks, 1, data.fromloc__c, 2, 4, 1); // 判断起点, 抛终点即可
                        }
                        return result
                    } else return []
                }
                // node.warn(newData);
                // node.warn(ku1);
                // node.warn(pallet__c);
                for (let i = 0; i < newData.length; i++) {
                    const element = newData[i];
                    const rowLoc = element.fromloc__c.substring(2, 4);
                    if (rowLoc === "01" || rowLoc === "04") {

                        async function isRequirement() {
                            // 判断 02 和 03 位置是否为空
                            let findRow = 0;
                            if (rowLoc === "01") findRow = 2;
                            if (rowLoc === "04") findRow = 3;
                            const findLoc = (lane__c, col__c, lay__c, findRow) => allLoc.filter(v2 => v2.row__c === findRow && v2.status__c === "占用" && v2.lane__c === lane__c && v2.col__c === col__c && v2.lay__c === lay__c)
                            const lane = +(element.fromloc__c.substring(0, 2))
                            const lay = +(element.fromloc__c.substring(4, 6))
                            const col = +(element.fromloc__c.substring(6, 8))
                            const res = findLoc(lane, col, lay, findRow)

                            // 找阻挡的库位，如果有 就移库
                            if (res && res.length) {
                                const task = await find("hs_stacker__c", { filters: [['stacker__c', '=', stacker], ['type_scurce__c', '=', "移库任务"], ['status__c', '!=', '已完成']] })
                                if (task.length) {
                                    return []
                                }

                                const findLoc2 = (lane__c, lay__c, col__c, findRow) => {
                                    return fDocs.filter(v2 => {
                                        let fromloc = `${lane__c}${findRow}${lay__c}${col__c}`
                                        return v2.fromloc__c === fromloc && v2.status__c != "已完成"
                                    })
                                }
                                // 查找同一个堆垛机的堆垛机列表 中 是否有 1或4巷道出库 旁边有货的错误
                                const res2 = findLoc2(element.fromloc__c.substring(0, 2), element.fromloc__c.substring(4, 6), element.fromloc__c.substring(6, 8), `0${findRow}`)
                                if (res2.length) {
                                    node.warn("移库顺序错误");
                                    return
                                }

                                // 1排出库时，2排阻挡  需要移库
                                async function CommonStackers(data, cmdtype, fromloc, nextloc, typeScource, priority, remove) {
                                    let doc = {
                                        time__c: time(),
                                        stacker__c: stacker,
                                        pallet__c: data.pallet__c,
                                        taskno__c: global.get('taskNo')(),
                                        product__c: data.product__c,
                                        fromloc__c: fromloc,
                                        nextloc__c: nextloc,
                                        cmdtype__c: cmdtype,
                                        type_scurce__c: typeScource, // 搬运任务
                                        priority__c: +(priority), // 优先级
                                        status__c: "未执行",
                                        remove__c: remove
                                    }
                                    await ins("hs_stacker__c", doc)
                                }
                                const { lane__c, row__c, col__c, lay__c } = res[0];
                                let column = 0;
                                if (col__c >= 1 && col__c <= 20) { column = 20 }
                                if (col__c > 20 && col__c < 60) { column = 40 }
                                if (col__c >= 60 && col__c <= 72) { column = 60 }
                                let fromLOC = `0${lane__c}0${row__c}0${lay__c}${col__c >= 10 ? col__c : "0" + col__c}`;
                                let destLOC = `0${lane__c}0201${column}` // x巷道2排1层 x列
                                await CommonStackers(element, "移库任务", fromLOC, destLOC, "移库任务", 13, "移库分解一") // 阻挡位 到 暂存位
                                new Promise((reslove, reject) => {
                                    setTimeout(async () => {
                                        await up("hs_stacker__c", element._id, { priority__c: 12, type_scurce__c: "移库任务", remove__c: "移库分解二" });
                                        await CommonStackers(element, "移库任务", destLOC, fromLOC, "移库任务", 11, "移库分解三") // 暂存位 到 阻挡位 
                                    }, 3000)
                                })
                                return []
                            } else {
                                if (['1090', '1092', '1094'].includes(element.nextloc__c) && ku1 === 0) {
                                    return await TaskOut(element)
                                } else if (['1047'].includes(element.nextloc__c) && ku2 === 0) {
                                    return await TaskOut(element)
                                } else if (['1121', '1135', '1140'].includes(element.nextloc__c) && ku3 === 0) {
                                    return await TaskOut(element)
                                }
                            }
                        }

                        if (['1090', '1092', '1094'].includes(element.nextloc__c) && ku1 === 0) {
                            return await isRequirement()
                        } else if (['1047'].includes(element.nextloc__c) && ku2 === 0) {
                            return await isRequirement()
                        } else if (['1121', '1135', '1140'].includes(element.nextloc__c) && ku3 === 0) {
                            return await isRequirement()
                        }
                    } else {
                        if (['1090', '1092', '1094'].includes(element.nextloc__c) && ku1 === 0) {
                            // node.warn(123);
                            return await TaskOut(element)
                        } else if (['1047'].includes(element.nextloc__c) && ku2 === 0) {
                            return await TaskOut(element)
                        } else if (['1121', '1135', '1140'].includes(element.nextloc__c) && ku3 === 0) {
                            return await TaskOut(element)
                        }
                        // 这里不能 return，出库不执行的情况下，可以执行入库，但不能移库
                    }
                }
            }

        }

    }

}

// 公共方法，可以放到Global全局中
function finalResults(pallet, plctask, product, fromRow, fromLay, fromColumn, toRow, toLay, toColumn, checkNum) {
    return [
        { payload: pallet },    // 托盘号
        { payload: fromRow },   // 来自排
        { payload: fromLay },   // 来自层
        { payload: fromColumn }, // 来自列
        { payload: toRow },     // 去排
        { payload: toLay },     // 去层
        { payload: toColumn },  // 去列
        { payload: checkNum },  // 检查号  020101020213
        { payload: Number(product) || 1 }, // 产品类型
        { payload: plctask },   // 任务号
    ]
}
// 传入的参数： inStock("pallet_240514", "taskno_666", "product_666", "2", "1", "1", "02030123")
function inStock(pallet, plctask, product, fromRow, fromLay, fromColumn, locDest) {
    // 处理终点 + 检查任务 + 将处理后的数据传递到FinalResults
    const dest = String(locDest);
    // const start = String(locStart);
    const v1 = +(dest.substring(0, 2))
    const toRow = +(dest.substring(2, 4));
    const toLay = +(dest.substring(4, 6));
    const toColumn = +(dest.substring(6, 8));
    const v5 = dest.substring(2, 8);
    const checkNum = `0${fromRow}0${fromLay}0${fromColumn}` + v5;
    // console.log(v1,v2,v3,v4,v5)
    // node.warn(checkNum);
    return finalResults(pallet, plctask, product, fromRow, fromLay, fromColumn, toRow, toLay, toColumn, checkNum);
}
function outStock(pallet, plctask, product, locStart, toRow, toLay, toColumn) {
    // 处理终点 + 检查任务 +  将处理后的数据传递到FinalResults
    const start = String(locStart);
    const v1 = +(start.substring(0, 2))
    const fromRow = +(start.substring(2, 4));//排
    const fromLay = +(start.substring(4, 6));//层
    const fromColumn = +(start.substring(6, 8));//列
    const v5 = start.substring(2, 8);//堆垛机校验
    const checkNum = v5 + `0${toRow}0${toLay}0${toColumn}`;
    // console.log(v1,v2,v3,v4,v5)
    // node.warn(checkNum);
    return finalResults(pallet, plctask, product, fromRow, fromLay, fromColumn, toRow, toLay, toColumn, checkNum);
}

global.set(['inStock', 'outStock'], [inStock, outStock])

// 公共方法，可以放到Global全局中
function finalResults(pallet, plctask, product, fromRow, fromLay, fromColumn, toRow, toLay, toColumn, checkNum) {
    return [
        { payload: pallet },    // 托盘号
        { payload: fromRow },   // 来自排
        { payload: fromLay },   // 来自层
        { payload: fromColumn }, // 来自列
        { payload: toRow },     // 去排
        { payload: toLay },     // 去层
        { payload: toColumn },  // 去列
        { payload: checkNum },  // 检查号
        { payload: Number(product) || 1 }, // 产品类型
        { payload: plctask },   // 任务号
    ]
}
function mvStock(pallet, plctask, product, locStart, locDest) {
    const start = String(locStart);
    const fromRow = +(start.substring(2, 4));//排
    const fromLay = +(start.substring(4, 6));//层
    const fromColumn = +(start.substring(6, 8));//列  
    const dest = String(locDest);
    const toRow = +(dest.substring(2, 4));
    const toLay = +(dest.substring(4, 6));
    const toColumn = +(dest.substring(6, 8));
    const checkNum = `0${fromRow}0${fromLay}0${fromColumn}0${toRow}0${toLay}0${toColumn}`;
