    graph[e.from].push({ to: e.to, cost: e.cost || 1, device_type: e.device_type });

    // 如果 direction == 0 (双向)，增加反向边
    if (e.direction === 0) {
      if (!graph[e.to]) graph[e.to] = [];
      graph[e.to].push({ to: e.from, cost: e.cost || 1, device_type: e.device_type });
    }

    // 注意：如果 direction == 2 表示 to->from 单向（特殊情况），可按需要处理
    if (e.direction === 2) {
      // 说明数据库以 e.from/e.to 表示相反方向，若你使用这种约定可在这里做额外处理
    }
  }
  return graph;
}

function dijkstra(graph, start, goal) {
  // dist map / prev map
  const dist = {};
  const prev = {};
  const pq = new MinPQ();

  // 初始化（所有节点的距离为 Infinity）
  for (const node of Object.keys(graph)) dist[node] = Infinity;
  if (!(start in dist)) dist[start] = Infinity; // start 可能不在 graph keys (孤立节点)
  dist[start] = 0;
  pq.push({ node: start, dist: 0 });

  while (!pq.isEmpty()) {
    const cur = pq.pop();
    const u = cur.node;
    const du = cur.dist;
    if (du > dist[u]) continue; // 已有更优解
    if (u === goal) break; // 找到最短到 goal

    const neighbors = graph[u] || [];
    for (const nb of neighbors) {
      const alt = du + nb.cost;
      if (alt < (dist[nb.to] ?? Infinity)) {
        dist[nb.to] = alt;
        prev[nb.to] = { from: u, edge: nb };
        pq.push({ node: nb.to, dist: alt });
      }
    }
  }
  node.warn(123);
  node.warn(goal);
  node.warn(dist);
  // 还原路径
  if (!(goal in dist) || dist[goal] === Infinity) return null;
  node.warn(123123);
  const path = [];
  let cur = goal;
  while (cur !== start) {
    const p = prev[cur];
    if (!p) { // 无法回溯（起点与终点不连通）
      return null;
    }
    path.unshift({ from: p.from, to: cur, edge: p.edge });
    cur = p.from;
  }
  return { cost: dist[goal], path };
}

