    stackerNo = loc[0].stacker__c;
  }

  // 根据类型确定 findPath 的参数
  let pathStart, pathEnd;
  if (type === "INBOUND") {
    pathStart = start; // 1022
    pathEnd = stackerNo;
  } else if (type === "OUTBOUND") {
    pathStart = stackerNo;
    pathEnd = end; // 1019
  } else if (type == "POINT") {
    pathStart = start;
    pathEnd = end;
  } else {
    node.warn("无效的路径类型");
    return null;
  }

  // 查找路径
  const path = await findPath(db, pathStart, pathEnd, type);
  if (path && path.length) {
    return path
  } else {
    node.warn('未找到匹配的路径');
    return null
  }
}

