const { MongoClient } = global.get("mongodb");

async function findPath(db, startNode, endNode, taskType) {
  // 从 MongoDB 取出可用的路径边
  const edges = await db.collection("tl_device_edge__c").find({ status__c: "可用" }).toArray();
  // node.warn(edges);

  // 允许的任务类型映射
  const allowedTypesMap = {
    INBOUND: ["INBOUND", "ALL"],
    OUTBOUND: ["OUTBOUND", "ALL"],
    POINT: ['POINT', 'ALL'],
    ANY: ["INBOUND", "OUTBOUND", "ALL"]
  };
  const allowedEdgeTypes = allowedTypesMap[taskType] || ["ALL"];

  // 构建邻接表
  const graph = {};
  for (const e of edges) {
    if (!allowedEdgeTypes.includes(e.task_type__c)) continue;

    if (e.direction__c === 0 || e.direction__c === 1) { // 方向 0：双向   1：正向
      graph[e.loc_start__c] = graph[e.loc_start__c] || [];
      graph[e.loc_start__c].push(e.loc_end__c);
    }
    if (e.direction__c === 0 || e.direction__c === 2) {
      graph[e.loc_end__c] = graph[e.loc_end__c] || [];
      graph[e.loc_end__c].push(e.loc_start__c);
    }
  }
  for (let item in graph) {
    node.warn(`路径节点： { ${item} : ${graph[item]} }`);
  }


  // BFS 查找路径
  const queue = [[startNode]];
  const visited = new Set([startNode]);
  while (queue.length > 0) {
    const path = queue.shift();
    const last = path[path.length - 1];
    if (last === endNode) return path; // 找到终点
    for (const neighbor of graph[last] || []) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        queue.push([...path, neighbor]);
      }
    }
  }
  return null;
}





async function RoutesFind(start, end, type) {
  const client = await MongoClient.connect("mongodb://localhost:27017");
  const db = client.db("steedos_tailaiFH");


  // 根据类型确定要查找的库位
  let stackerNo = ""
  if (['INBOUND', 'OUTBOUND'].includes(type)) {
    const locationToFind = (type === "INBOUND") ? end : start;
    const loc = await db.collection("tl_storage__c").find({ location__c: locationToFind }).toArray();
    if (!loc.length) { node.warn("未找到库位编码"); return null }
    if (loc.length > 1) { node.warn("库位编码异常"); return null }
    stackerNo = loc[0].stacker__c;
  }

  // 根据类型确定 findPath 的参数
  let pathStart, pathEnd;
  if (type === "INBOUND") {
    pathStart = start; // 1022
    pathEnd = stackerNo;
  } else if (type === "OUTBOUND") {
    pathStart = stackerNo;
    pathEnd = end; // 1019
  } else if (type == "POINT") {
    pathStart = start;
    pathEnd = end;
  } else {
    node.warn("无效的路径类型");
    return null;
  }

  // 查找路径
  const path = await findPath(db, pathStart, pathEnd, type);
  if (path && path.length) {
    return path
  } else {
    node.warn('未找到匹配的路径');
    return null
  }
}
