async function OutWarehouse(materialName, batch, productionDate, outTotalQuantity) {

  const totalGoods = await db.find("kd_keepwarm_stock_detail__c", {
    query: {
      material_name__c: String(materialName).trim(),
      batch__c: String(batch).trim(),
      production_date__c: String(productionDate).trim(),
      stock_status__c: "在库"
    }
  })
  node.warn(totalGoods);
  if (!totalGoods || !totalGoods.length) return { success: false, message: `查询错误：根据 ${materialName} 未找到匹配的物料` };

  const stockQuantity = totalGoods.reduce((sum, item) => sum + (item.now_quantity__c || 0), 0); //*  计算库存当前数量 累加
  if (outTotalQuantity <= stockQuantity) {
    // node.warn("可以正常出库");


    // 定义分组规则
    const groupMap = {
      '3': 'A', '4': 'A', "5": "A", "6": "A", "7": "A", "8": "A",    // 3-8 为一组
      '10': "B", '11': "B", '12': "B", '13': "B", '14': "B", '15': "B", // 10-15 是一组
      '17': 'C', '18': 'C', '19': 'C', '20': 'C'   // 17、18、19、20 为一组
    };
    // 对象结构：列：｛ 分组ABC: ｛ 层： ｛｝｝｝
    function groupByColGroupLayer(data, groupMap) {
      const result = {};
      for (const item of data) {
        const groupKey = groupMap[item.row__c];
        if (!groupKey) continue;
        const { col__c: col, lay__c: lay } = item;
        result[col] ??= {};
        result[col][groupKey] ??= {};
        result[col][groupKey][lay] ??= [];
        result[col][groupKey][lay].push(item);
      }
      return result;
    }
    const grouped = groupByColGroupLayer(totalGoods, groupMap);
    // node.warn("对象结构");
    // node.warn(grouped);


    let selectNumber = 0; // 每次循环选择的数据
    let outStockQuantity = outTotalQuantity
    let finiallyArr = [] // 最终找到的数据
    for (const [colKey, colVal] of Object.entries(grouped)) {
      for (const [groupKey, groupVal] of Object.entries(colVal)) {
        for (const [layerKey, layerData] of Object.entries(groupVal)) {


          // node.warn(`${colKey}列 - ${groupKey}组 - ${layerKey}层  --  ${layerData.length}个`);

          // ***** 出库也要排序的、因为找靠过道的货物先出
          // 3-8排：8、7、6、5、4、3 这样寻找 【出库】
          // 10-15排：15、14、13、12、11、10 这样寻找 【出库】
          // 17-20排：17、18、19、20 这样寻找 【出库】
          const groups = [
            { rows: [3, 4, 5, 6, 7, 8], order: 'desc' },
            { rows: [10, 11, 12, 13, 14, 15], order: 'asc' },
            { rows: [17, 18, 19, 20], order: 'asc' }
          ];
          const dataSort = layerData.sort((a, b) => {
            // ① 按列排序  升序
            if (a.col__c !== b.col__c) return a.col__c - b.col__c;
            // ② 按层排序   升序
            if (a.lay__c !== b.lay__c) return a.lay__c - b.lay__c;
            // ③ 按 row__c 分组排序
            for (const { rows, order } of groups) {
              if (rows.includes(a.row__c) || rows.includes(b.row__c)) {
                return order === 'asc' ? a.row__c - b.row__c : b.row__c - a.row__c;
              }
            }
            // ④ 默认按 row__c 升序兜底
            return a.row__c - b.row__c;
          });
          if (dataSort.length) {
            for (const item of dataSort) {
              if (outStockQuantity <= item.now_quantity__c) {
                // 要出库的数量 <= 托盘上的物料总数量
                // 更新库存
                // 并且是半托回库
                finiallyArr.push(item)
                // node.warn(`库存总数量：${stockQuantity}, 出库数量：${outTotalQuantity}, 剩余库存数量：${surplus}, 选择托盘数量：${finiallyArr.length}`);

                await db.updateOne("kd_keepwarm_stock_detail__c", item._id, { final_quantity__c: item.now_quantity__c - outStockQuantity, stock_status__c: "正在出库" })

                return { success: true, data: finiallyArr, message: "查找成功" }
              } else {
                outStockQuantity = outStockQuantity - item.now_quantity__c;
                finiallyArr.push(item)

                await db.updateOne("kd_keepwarm_stock_detail__c", item._id, { final_quantity__c: 0, stock_status__c: "正在出库" })

              }
            }

          }
        }
      }
    }
  } else {
    return { success: false, message: `查询错误： ${materialName} 库存不足` }
  }

}


