async function Distribution(material_name__c, batch__c, production_date__c) {
  const fdoc = await db.find("kd_keepwarm_stock__c", {
    query: { material_name__c: String(material_name__c).trim(), batch__c: String(batch__c).trim(), production_date__c: String(production_date__c).trim() }
  })
  if (fdoc.length) { 

    let isFind = false;
    async function FindSameMaterial(sameMaterial) {
      // const groups = [
      //   { rows: [3, 4, 5, 6, 7, 8], order: 'desc' },  // 出库：按照巷道一侧先查找 8、7、6、5、4、3
      //   { rows: [10, 11, 12, 13, 14, 15], order: 'asc' },
      //   { rows: [17, 18, 19, 20], order: 'asc' }
      // ];
      // const dataSort = sameMaterial.sort((a, b) => {
      //   // ① 按列排序
      //   if (a.col__c !== b.col__c) return a.col__c - b.col__c;  // 按照列 升序
      //   // ② 按层排序
      //   if (a.lay__c !== b.lay__c) return a.lay__c - b.lay__c;  // 按照层 升序

      //   // ③ 按 row__c 分组排序
      //   for (const { rows, order } of groups) {
      //     if (rows.includes(a.row__c) || rows.includes(b.row__c)) {
      //       return order === 'asc' ? a.row__c - b.row__c : b.row__c - a.row__c;
      //     }
      //   }
      //   // ④ 默认按 row__c 升序兜底
      // return a.row__c - b.row__c;
      // });




      // [
      //   { row__c: 13, col__c: 1, lay__c: 1 },
      //   { row__c: 19, col__c: 1, lay__c: 1 },
      //   { row__c: 6,  col__c: 1, lay__c: 1 },
      // ]
      const dataSort = sameMaterial.sort((a, b) => {
        // 1️⃣ 按列排序
        if (a.col__c !== b.col__c) return a.col__c - b.col__c;

        // 2️⃣ 按层排序
        if (a.lay__c !== b.lay__c) return a.lay__c - b.lay__c;

        // 3️⃣ 按排分组排序
        const group1 = [3, 4, 5, 6, 7, 8];      // 降序
        const group2 = [10, 11, 12, 13, 14, 15]; // 升序
        const group3 = [17, 18, 19, 20];         // 升序

        // 判断每个元素属于哪个组
        const getGroup = (row) => {
          if (group1.includes(row)) return 1;
          if (group2.includes(row)) return 2;
          if (group3.includes(row)) return 3;
          return 0; // 不在分组
        };

        const groupA = getGroup(a.row__c);
        const groupB = getGroup(b.row__c);

        // 🔹 不在同一组，按组顺序排列
        if (groupA !== groupB) return groupA - groupB;

        // 🔹 在同一组内，按组规则排序
        if (groupA === 1) return b.row__c - a.row__c; // group1 降序
        return a.row__c - b.row__c; // 其他组升序
      });

      // node.warn(1);
      // node.warn(dataSort);
      async function FindEmpty(findRow, col, lay) {
        const empty = await db.find("kd_keepwarm_stock__c", {
          query: {
            row__c: findRow,
            col__c: col,
            lay__c: lay,
            shelf_status__c: "空闲",
            pallet_status__c: "空闲"
          }
        });
        return empty.length ? empty[0] : false;
      }

      // 定义各个区间组：rows 表示排号范围，direction 控制查找方向
      const rowGroups = [
        { rows: [3, 4, 5, 6, 7, 8], direction: "forward" },
        { rows: [10, 11, 12, 13, 14, 15], direction: "backward" },
        { rows: [17, 18, 19, 20], direction: "backward" }
      ];

      for (const item of dataSort) {
        const position = item.position__c; // 040101
        const row = +(position.substring(0, 2));
        const col = +(position.substring(2, 4));
        const lay = +(position.substring(4, 6));

        // 查找当前 row 属于哪个 group
        const group = rowGroups.find(g => g.rows.includes(row));
        if (!group) continue;

        const { rows, direction } = group;
        const currentIndex = rows.indexOf(row);
        if (currentIndex === -1) continue;

        // 获取需要检查的“后续排”或“前序排”
        const rowsToCheck = direction === "forward" ? rows.slice(currentIndex + 1) : rows.slice(0, currentIndex).reverse();
        if (!rowsToCheck.length) continue;

        // 并发检查所有空闲情况
        const results = await Promise.all(rowsToCheck.map(r => FindEmpty(r, col, lay)));

        // 如果都空闲（每个 FindEmpty 返回非 false）
        if (results.every(Boolean)) {
          // node.warn(results); // 输出第一个空闲位
          if (results.length) {
            // node.warn(123123);
            node.warn(results[0].loc_name__c);
            return { success: true, data: results[0] }
          }
        }
      }
    }

    const result = await FindSameMaterial(fdoc)
    // node.warn(`res: ${result}`);
    if (result) {
      // 找到相同的
      return result
    } else {
      // 如果有相同物料、但是都不 可以分配到一起、那么需要分配一个新库位才可以
      const findEmpty = await assignEmptyLoc()
      return findEmpty
    }


  } else {
    node.warn("库中没有相同的物料和批次");
    const findEmpty = await assignEmptyLoc()
    return findEmpty
  }
}


