async function SC_addOrder(palletno, types, start, dest, uuid) {


    const API_NAME = "2.添加订单"
    const API_URL = "/wapwss/api/wss/order/add"
    async function logRecord({ statusCode = 500, responseCode = 500, message = "未知错误", success = false }) {
        await db.insertOne("kd_keepwarm_sc_record__c", {
            time__c: global.get("time")(),
            // instruct_no__c: instruct_no,
            status_code__c: statusCode,
            response_code__c: responseCode,
            response_message__c: message,
            req_name__c: API_NAME,
            req_address__c: API_URL,
            is_success__c: success ? "成功" : "失败"
        });
    }

    // 2、添加订单 
    // 入库任务：添加订单的起始位置和最终位置
    // 出库任务：根据货位的先后添加位置
    // 发送接口结果：添加到与世仓接口表中、并且更新主任务
    try {

        let palletId = palletno //  "kd0000123456"
        let type = types // "StockIn"
        let startLoc = start // "A013013001";
        let destLoc = dest // "A003008002"
        let uniqueId = uuid // "asdjilnasd2" // id 不可重复  asdjilnasd2

        const { status, data } = await api.post('/wapwss/api/wss/order/add', {
            "bindType": "Undefine",
            "completed": false,
            "createBy": "WMS",
            "createTime": null,
            "fromPos": startLoc,
            "homePointFlag": false,
            "orderType": type,
            "palletID": palletId,
            "priority": 0,
            "refOrderId": uniqueId,
            "toPos": destLoc,
            "updateTime": null,
            "wMSId": 0,
            "warehouseCode": "A"
        })
        if (status !== 200) { // 网络层异常
            await logRecord({ statusCode: status, message: "HTTP状态码异常" });
            return { success: false, message: "HTTP状态码异常" };
        }
        if (data?.code !== 200) {    // 接口业务层异常
            await logRecord({ statusCode: status, responseCode: data?.code || 500, message: data?.message ?? "接口返回错误" });
            return { success: false, message: data?.message ?? "接口返回错误" };
        }
        const result = data;
        // node.warn(result);
        if (result && result.success) {
            return { success: true, message: "添加订单成功" };
        } else {
            return { success: false, message: "添加订单失败" };
        }
    } catch (error) {
        node.warn(error);
        await logRecord({ message: error?.message || "请求异常" });
        return { success: false, message: error?.message || "请求异常" };
    };
}

